mapper.select:
SELECT r.room_id AS roomId, r.floor_id AS floorId, f.floor_num AS floorNum, r.room_name AS roomName, r.seat_count AS seatCount, r.open_time AS openTime, r.close_time AS closeTime, r.room_type AS roomType, r.description AS description, r.status AS status, (SELECT COUNT(*) FROM study_seat s WHERE s.room_id = r.room_id AND s.status = 1) AS usableSeats, (SELECT COUNT(*) FROM study_seat s WHERE s.room_id = r.room_id AND s.status = 1 AND s.seat_id NOT IN ( SELECT o.seat_id FROM booking_order o WHERE o.booking_date = CURDATE() AND o.status IN (0, 1) AND o.start_time <= CURTIME() AND o.end_time > CURTIME() )) AS freeNow FROM study_room r LEFT JOIN library_floor f ON f.floor_id = r.floor_id WHERE r.status = 1
AND r.floor_id = #{floorId}
AND r.room_type = #{roomType}
AND r.room_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY f.floor_num, r.room_id
